from scipy.special import comb

n = 35
results = {}

# Range of a: 12, 13, 14, 15, 16, 17
for a in range(12, 18):
    k = n - 2 * a

    # Binomial coefficient: C(a-1, k-1)
    N_top = a - 1
    K_bottom = k - 1

    # Calculate C(a-1, k-1)
    try:
        C = comb(N_top, K_bottom)
    except ValueError:
        C = 0

    # Check divisibility: k | C
    is_divisible = (C % k == 0)

    results[a] = {
        'k': k,
        'C_value': int(C),
        'divisible': is_divisible
    }

for a, res in results.items():
    print(f"n={n}, a={a}: k={res['k']}. C(a-1, k-1) = {res['C_value']}. Divisibility check (k | C): {res['divisible']}")

